                description: "Return the sealed BlobManifest JSON (D-Bus/gRPC identity + methods)."
                    .into(),
                input_schema: json!({
                    "type": "object",
                    "properties": {
                        "plugin_id": {"type": "string"}
                    },
                    "required": ["plugin_id"]
70→                }),
                annotations: None,
